const body = ($input.first().json.body) || $input.first().json || [];
const pages = Array.isArray(body) ? body : (body.pages || []);
const all = [];
(function flat(arr){ for (const p of (arr||[])) { all.push(p); if (p.pages) flat(p.pages); } })(pages);
const page = all.find(p => p.id === 'q7wz-44812');
const rules_md = (page && page.content) ? String(page.content) : '';
const rules_present = !!rules_md && rules_md.trim().length > 50;
return [{ json: { rules_md, rules_present, page_found: !!page } }];

const current = $('Hash Rules').first().json.rules_sha256;
let maxHours = 0;
try { maxHours = Number($('Get Sync Summary').first().json.max_hours) || 0; } catch(e){}
const meta = {};
try { for (const r of $('Get Agent IDs').all()) { meta[r.json.agent_id] = r.json; } } catch(e){}
const live = $input.all();
const stale = [], noProv = [], ok = [];
for (const it of live) {
  const a = it.json;
  const sys = a.system || '';
  const m = sys.match(/rules_sha256=([0-9a-f]{64})/);
  const tier = (meta[a.id] && meta[a.id].tier_label) || a.name || a.id;
  if (!m) { noProv.push(tier); }
  else if (m[1] !== current) { stale.push(tier + ' (' + m[1].slice(0,8) + ' vs ' + String(current).slice(0,8) + ')'); }
  else { ok.push(tier); }
}
let severity = 'INFO', problem = false, message = '', details = '';
if (live.length === 0) {
  severity = 'CRITICAL'; problem = true;
  message = 'Freshness check nie odczytał żadnego żywego agenta.';
  details = 'Sprawdź Get Live Agent / klucz Anthropic.';
} else if (noProv.length) {
  severity = 'CRITICAL'; problem = true;
  message = 'Agent(y) Managed Agents bez znacznika prowenancji zasad — definicja uszkodzona lub zmieniona poza Sync.';
  details = 'Tiery: ' + noProv.join(', ') + '. Uruchom Sync Agent Definitions (v1) i sprawdź, czy agent nie był zmieniany ręcznie.';
} else if (stale.length) {
  severity = 'WARN'; problem = true;
  message = 'Zasady globalne w ClickUp zmieniły się, ale agenci niosą starszą wersję — dryf zasad.';
  details = 'Stale tiery: ' + stale.join('; ') + '. Uruchom Sync Agent Definitions (v1) (przy dryfie poza Sync użyj force=true), aby wgrać aktualne zasady. Bieżący hash: ' + String(current).slice(0,12) + '.';
} else if (maxHours > 24) {
  severity = 'WARN'; problem = true;
  message = 'Sync agentów nie wykonał się skutecznie od ponad 24h (treść na razie zgodna).';
  details = 'Najstarszy synced_at: ' + maxHours + 'h temu. Sprawdź, czy Sync Agent Definitions (v1) jest aktywny i czy schedule działa.';
} else {
  message = 'Agenci aktualni.'; details = 'OK tiery: ' + ok.join(', ') + '.';
}
return [{ json: { problem, severity, message, details, current_sha: current, ok: ok.length, stale: stale.length, no_provenance: noProv.length, max_hours: maxHours } }];
